DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE TABLE_NAME = 'REPORT_TEMPLATES';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE REPORT_TEMPLATES (
                ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                NAME VARCHAR2(100) NOT NULL,
                DESCRIPTION VARCHAR2(4000),
                CONFIG_JSON CLOB,
                CREATED_BY VARCHAR2(100) DEFAULT ''SYSTEM'' NOT NULL,
                CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
                UPDATED_BY VARCHAR2(100),
                UPDATED_AT TIMESTAMP
            )';
    END IF;
END;
/

DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE TABLE_NAME = 'ROLE_MODULE_ACCESS';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE ROLE_MODULE_ACCESS (
                ROLE        VARCHAR2(50)   NOT NULL,
                MODULE_CODE VARCHAR2(100)  NOT NULL,
                ENABLED     CHAR(1)        DEFAULT ''Y'',
                CREATED_AT  TIMESTAMP      DEFAULT CURRENT_TIMESTAMP,
                UPDATED_AT  TIMESTAMP,
                CONSTRAINT PK_ROLE_MODULE_ACCESS PRIMARY KEY (ROLE, MODULE_CODE)
            )';
    END IF;
END;

MERGE INTO ROLE_MODULE_ACCESS t USING (SELECT 'MAKER' role, 'UPLOAD' module_code FROM dual) s ON (t.role = s.role AND t.module_code = s.module_code) WHEN NOT MATCHED THEN INSERT (role, module_code, enabled) VALUES (s.role, s.module_code, 'Y');
MERGE INTO ROLE_MODULE_ACCESS t USING (SELECT 'MAKER' role, 'REPORTS' module_code FROM dual) s ON (t.role = s.role AND t.module_code = s.module_code) WHEN NOT MATCHED THEN INSERT (role, module_code, enabled) VALUES (s.role, s.module_code, 'Y');
