DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM ALL_TABLES
    WHERE TABLE_NAME = 'USER_ROLE_MAP';

    IF v_count = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE USER_ROLE_MAP (
                USER_ID    VARCHAR2(200) NOT NULL,
                ROLE       VARCHAR2(50)  NOT NULL,
                ENABLED    CHAR(1)       DEFAULT ''Y'',
                CREATED_AT TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
                CONSTRAINT PK_USER_ROLE_MAP PRIMARY KEY (USER_ID, ROLE)
            )';
    END IF;
END;

DECLARE
    PROCEDURE seed_role(p_user VARCHAR2, p_role VARCHAR2) IS
        v_exists INTEGER;
    BEGIN
        SELECT COUNT(*) INTO v_exists FROM USER_ROLE_MAP WHERE USER_ID = p_user AND ROLE_NAME = p_role;
        IF v_exists = 0 THEN
            INSERT INTO USER_ROLE_MAP (USER_ID, ROLE_NAME, ENABLED) VALUES (p_user, p_role, 'Y');
        END IF;
    END;
BEGIN
    seed_role('samson', 'ADMIN');
    seed_role('samson', 'APPROVER');
    seed_role('samson', 'REVIEWER');
    seed_role('samson', 'MAKER');
    seed_role('dev-user', 'ADMIN');
    seed_role('dev-user', 'APPROVER');
    seed_role('dev-user', 'REVIEWER');
    seed_role('dev-user', 'MAKER');
END;
/

DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM user_tables WHERE table_name = 'WORKFLOW_ACTIONS';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE WORKFLOW_ACTIONS (
                ACTION_CODE VARCHAR2(50) PRIMARY KEY,
                LABEL       VARCHAR2(100) NOT NULL,
                ENABLED     CHAR(1) DEFAULT ''Y'' NOT NULL,
                CREATED_AT  TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )';
    END IF;

    SELECT COUNT(*) INTO v_count FROM user_tables WHERE table_name = 'ROLE_WORKFLOW_ACTION_ACCESS';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE ROLE_WORKFLOW_ACTION_ACCESS (
                ROLE_NAME   VARCHAR2(50) NOT NULL,
                FROM_STATUS VARCHAR2(50) NOT NULL,
                ACTION_CODE VARCHAR2(50) NOT NULL,
                ENABLED     CHAR(1) DEFAULT ''Y'' NOT NULL,
                CREATED_AT  TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UPDATED_AT  TIMESTAMP,
                CONSTRAINT PK_ROLE_WORKFLOW_ACTION_ACCESS PRIMARY KEY (ROLE_NAME, FROM_STATUS, ACTION_CODE),
                CONSTRAINT FK_ROLE_WORKFLOW_ACTION_ROLE FOREIGN KEY (ROLE_NAME) REFERENCES ROLES(ROLE_NAME),
                CONSTRAINT FK_ROLE_WORKFLOW_ACTION_CODE FOREIGN KEY (ACTION_CODE) REFERENCES WORKFLOW_ACTIONS(ACTION_CODE)
            )';
        EXECUTE IMMEDIATE 'CREATE INDEX IDX_RWF_ACTION_STATUS ON ROLE_WORKFLOW_ACTION_ACCESS (FROM_STATUS)';
        EXECUTE IMMEDIATE 'CREATE INDEX IDX_RWF_ACTION_ROLE ON ROLE_WORKFLOW_ACTION_ACCESS (ROLE_NAME)';
    END IF;
END;
/

