DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM user_tab_cols
    WHERE table_name = 'JSON_CONFIG' AND column_name = 'SCHEMA_STATUS';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE JSON_CONFIG ADD (SCHEMA_STATUS VARCHAR2(20))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM user_tab_cols
    WHERE table_name = 'JSON_CONFIG' AND column_name = 'SCHEMA_VERSION';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE JSON_CONFIG ADD (SCHEMA_VERSION NUMBER(10))';
    END IF;

    FOR c IN (
        SELECT constraint_name
        FROM user_constraints
        WHERE table_name = 'JSON_CONFIG'
          AND constraint_type = 'U'
          AND constraint_name <> 'UQ_JSON_CONFIG_KEY_VERSION'
          AND constraint_name IN (
              SELECT ucc.constraint_name
              FROM user_cons_columns ucc
              WHERE ucc.table_name = 'JSON_CONFIG'
              GROUP BY ucc.constraint_name
              HAVING COUNT(*) = 1 AND MAX(ucc.column_name) = 'CONFIG_KEY'
          )
    ) LOOP
        EXECUTE IMMEDIATE 'ALTER TABLE JSON_CONFIG DROP CONSTRAINT ' || c.constraint_name;
    END LOOP;

    SELECT COUNT(*) INTO v_count FROM user_constraints
    WHERE table_name = 'JSON_CONFIG' AND constraint_name = 'UQ_JSON_CONFIG_KEY_VERSION';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE JSON_CONFIG ADD CONSTRAINT UQ_JSON_CONFIG_KEY_VERSION UNIQUE (CONFIG_KEY, SCHEMA_VERSION)';
    END IF;

    SELECT COUNT(*) INTO v_count FROM user_indexes
    WHERE index_name = 'IDX_JSON_CONFIG_KEY_STATUS';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE INDEX IDX_JSON_CONFIG_KEY_STATUS ON JSON_CONFIG (CONFIG_KEY, SCHEMA_STATUS)';
    END IF;

    SELECT COUNT(*) INTO v_count FROM user_tab_cols
    WHERE table_name = 'DOCUMENT_PARENT' AND column_name = 'SCHEMA_BINDING_MODE';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE DOCUMENT_PARENT ADD (SCHEMA_BINDING_MODE VARCHAR2(30))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM user_tab_cols
    WHERE table_name = 'DOCUMENT_PARENT' AND column_name = 'SCHEMA_VERSION';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE DOCUMENT_PARENT ADD (SCHEMA_VERSION NUMBER(10) DEFAULT 0)';
        EXECUTE IMMEDIATE 'UPDATE DOCUMENT_PARENT SET SCHEMA_VERSION = 0 WHERE SCHEMA_VERSION IS NULL';
    END IF;

    EXECUTE IMMEDIATE q'[UPDATE DOCUMENT_PARENT SET SCHEMA_BINDING_MODE = 'FLOATING_SANDBOX' WHERE SCHEMA_BINDING_MODE IS NULL AND SCHEMA_VERSION = 0]';

    SELECT COUNT(*) INTO v_count FROM user_indexes
    WHERE index_name = 'IDX_DOC_SCHEMA_VERSION';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE INDEX IDX_DOC_SCHEMA_VERSION ON DOCUMENT_PARENT (SCHEMA_VERSION)';
    END IF;

    EXECUTE IMMEDIATE q'[SELECT COUNT(*) FROM JSON_CONFIG WHERE CONFIG_KEY = 'UPLOAD_CONFIG' AND SCHEMA_STATUS = 'SANDBOX']'
        INTO v_count;
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE q'[
            INSERT INTO JSON_CONFIG (ID, CONFIG_KEY, CONFIG_VALUE, SCHEMA_STATUS, SCHEMA_VERSION, UPDATED_BY, UPDATED_AT)
            SELECT JSON_CONFIG_SEQ.NEXTVAL, seed.CONFIG_KEY, seed.CONFIG_VALUE, 'SANDBOX', 0, seed.UPDATED_BY, seed.UPDATED_AT
            FROM JSON_CONFIG seed
            WHERE seed.ID = (
                SELECT MAX(src.ID)
                FROM JSON_CONFIG src
                WHERE src.CONFIG_KEY = 'UPLOAD_CONFIG'
                  AND src.SCHEMA_STATUS IS NULL
            )
        ]';
    END IF;
END;

DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE TABLE_NAME = 'DATE_PRESET_MASTER';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE TABLE DATE_PRESET_MASTER (
            ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            PRESET_CODE VARCHAR2(100) NOT NULL,
            PRESET_NAME VARCHAR2(200) NOT NULL,
            PRESET_DESCRIPTION VARCHAR2(500),
            START_RULE VARCHAR2(100) NOT NULL,
            END_RULE VARCHAR2(100) NOT NULL,
            ENABLED CHAR(1) DEFAULT ''Y'' NOT NULL,
            DISPLAY_ORDER NUMBER(10) DEFAULT 0 NOT NULL,
            CREATED_BY VARCHAR2(100),
            CREATED_TIME TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UPDATED_BY VARCHAR2(100),
            UPDATED_TIME TIMESTAMP
        )';
    END IF;

    SELECT COUNT(*) INTO v_count
    FROM USER_CONSTRAINTS
    WHERE TABLE_NAME = 'DATE_PRESET_MASTER'
      AND CONSTRAINT_NAME = 'UQ_DATE_PRESET_MASTER_CODE';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE DATE_PRESET_MASTER ADD CONSTRAINT UQ_DATE_PRESET_MASTER_CODE UNIQUE (PRESET_CODE)';
    END IF;
END;

