    SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE TABLE_NAME = 'REPORT_FILTER_PRESET_MAP';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'CREATE TABLE REPORT_FILTER_PRESET_MAP (
            ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            REPORT_CODE VARCHAR2(150) NOT NULL,
            FILTER_KEY VARCHAR2(200) NOT NULL,
            PRESET_CODE VARCHAR2(100) NOT NULL,
            ENABLED CHAR(1) DEFAULT ''Y'' NOT NULL,
            DISPLAY_ORDER NUMBER(10) DEFAULT 0 NOT NULL,
            CREATED_BY VARCHAR2(100),
            CREATED_TIME TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UPDATED_BY VARCHAR2(100),
            UPDATED_TIME TIMESTAMP,
            CONSTRAINT FK_RPT_FILTER_PRESET_CODE FOREIGN KEY (PRESET_CODE) REFERENCES DATE_PRESET_MASTER(PRESET_CODE)
        )';
    END IF;

    SELECT COUNT(*) INTO v_count
    FROM USER_CONSTRAINTS
    WHERE TABLE_NAME = 'REPORT_FILTER_PRESET_MAP'
      AND CONSTRAINT_NAME = 'UQ_RPT_FILTER_PRESET';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE REPORT_FILTER_PRESET_MAP ADD CONSTRAINT UQ_RPT_FILTER_PRESET UNIQUE (REPORT_CODE, FILTER_KEY, PRESET_CODE)';
    END IF;
END;

